function buildShapeShader(config) {
  const combine = config.enableLiquid ? 'smin' : 'min';
  const combineCall = (current, next) => config.enableLiquid
    ? `${combine}(${current}, ${next}, blendK)`
    : `${combine}(${current}, ${next})`;

  if (config.layout === 'circles') {
    const positions = [
      [-0.68, 0.08],
      [-0.34, -0.08],
      [0.0, 0.08],
      [0.34, -0.08],
      [0.68, 0.08]
    ];
    const declarations = positions.map(([x, y], index) => `
      vec2 circleCenter${index} = mix(vec2(${x.toFixed(2)}, ${y.toFixed(2)}), vec2(0.0), pMerge);
      float dShape${index} = length(st - circleCenter${index}) - mix(0.16, 0.58, pMerge);
    `).join('');
    const union = positions.slice(1).reduce(
      (current, _, index) => combineCall(current, `dShape${index + 1}`),
      'dShape0'
    );
    return `${declarations}\nfloat dShapes = ${union};`;
  }

  if (config.layout === 'gameSymbols') {
    return `
      float symbolScale = mix(0.16, 0.58, pMerge);
      vec2 squareCenter = mix(vec2(-0.66, 0.0), vec2(0.0), pMerge);
      vec2 triangleCenter = mix(vec2(-0.22, 0.0), vec2(0.0), pMerge);
      vec2 circleCenter = mix(vec2(0.22, 0.0), vec2(0.0), pMerge);
      vec2 crossCenter = mix(vec2(0.66, 0.0), vec2(0.0), pMerge);

      float dShape0 = sdRoundedBox(st - squareCenter, vec2(symbolScale), mix(0.035, 0.055, pMerge));
      vec2 trianglePoint = st - triangleCenter;
      float triangleBottom = -trianglePoint.y - symbolScale;
      float triangleSides = trianglePoint.y + 2.0 * abs(trianglePoint.x) - symbolScale;
      float dShape1 = max(triangleBottom, triangleSides);
      float dShape2 = length(st - circleCenter) - symbolScale;

      vec2 crossPoint = st - crossCenter;
      crossPoint = mat2(0.7071068, -0.7071068, 0.7071068, 0.7071068) * crossPoint;
      float crossWidth = mix(0.065, 0.24, pMerge);
      float crossLength = 1.4142136 * symbolScale - crossWidth + mix(0.007, 0.0, pMerge);
      float dCrossV = sdRoundedBox(crossPoint, vec2(crossWidth, crossLength), crossWidth * 0.38);
      float dCrossH = sdRoundedBox(crossPoint, vec2(crossLength, crossWidth), crossWidth * 0.38);
      float dShape3 = min(dCrossV, dCrossH);

      float dShapes = ${combineCall(combineCall(combineCall('dShape0', 'dShape1'), 'dShape2'), 'dShape3')};
    `;
  }

  if (config.layout === 'appleLogo') {
    return `
      vec2 appleUv = st / ${Number(config.maskScale ?? 0.92).toFixed(2)} + 0.5;
      float appleBounds = step(0.0, appleUv.x) * step(appleUv.x, 1.0)
        * step(0.0, appleUv.y) * step(appleUv.y, 1.0);
      float appleSdf = texture2D(u_wordmark, appleUv).r;
      float dApple = (appleSdf - 0.5) * 0.345;
      dApple = mix(0.18, dApple, appleBounds);
      float logoLiquidPhase = sin(pMerge * 3.14159265);
      float logoRipple = (
        sin(appleUv.y * 28.0 + p * 9.0)
        + sin(appleUv.x * 23.0 - p * 7.0)
      ) * 0.0025 * logoLiquidPhase;
      dApple += logoRipple * appleBounds;
      float frameContract = smoothstep(0.55, 0.92, pMerge);
      vec2 frameSize = mix(vec2(0.47, 0.44), vec2(0.89, 0.50), frameContract);
      float frameRadius = mix(0.18, 0.045, frameContract);
      float dFrame = sdRoundedBox(st, frameSize, frameRadius);
      float contourBlend = smoothstep(0.45, 0.70, pMerge);
      float dShapes = mix(dApple, dFrame, contourBlend);
    `;
  }

  if (config.layout === 'arches') {
    const archHalfWidth = 0.22;
    const archPitch = archHalfWidth * 2 + GAP_PX / 688;
    return `
      vec2 archSize = mix(vec2(${archHalfWidth.toFixed(2)}, 0.40), vec2(0.62, 0.46), pMerge);
      vec2 archCenter0 = mix(vec2(${(-archPitch).toFixed(4)}, 0.0), vec2(0.0), pMerge);
      vec2 archCenter1 = vec2(0.0);
      vec2 archCenter2 = mix(vec2(${archPitch.toFixed(4)}, 0.0), vec2(0.0), pMerge);
      float dShape0 = sdArch(st - archCenter0, archSize);
      float dShape1 = sdArch(st - archCenter1, archSize);
      float dShape2 = sdArch(st - archCenter2, archSize);
      float dShapes = ${combineCall(combineCall('dShape0', 'dShape1'), 'dShape2')};
    `;
  }

  if (config.layout === 'radialFan') {
    const cards = [
      [-0.54, -0.10, 1.28],
      [-0.43, 0.10, 0.86],
      [-0.25, 0.25, 0.43],
      [0.00, 0.30, 0.00],
      [0.25, 0.25, -0.43],
      [0.43, 0.10, -0.86],
      [0.54, -0.10, -1.28]
    ];
    const declarations = cards.map(([x, y, angle], index) => `
      vec2 fanCenter${index} = mix(vec2(${x.toFixed(2)}, ${y.toFixed(2)}), vec2(0.0), pMerge);
      vec2 fanPoint${index} = rotate2d(${angle.toFixed(2)} * (1.0 - pMerge)) * (st - fanCenter${index});
      vec2 fanSize${index} = mix(vec2(0.072, 0.15), vec2(0.58, 0.42), pMerge);
      float dShape${index} = sdRoundedBox(fanPoint${index}, fanSize${index}, mix(0.026, 0.045, pMerge));
    `).join('');
    const union = cards.slice(1).reduce(
      (current, _, index) => combineCall(current, `dShape${index + 1}`),
      'dShape0'
    );
    return `${declarations}\nfloat dShapes = ${union};`;
  }

  if (config.layout === 'cardDeck') {
    const deckHalfWidth = 0.09;
    const deckPitch = deckHalfWidth * 2 + GAP_PX / 688;
    const cards = Array.from({ length: 6 }, (_, index) => [
      (index - 2.5) * deckPitch,
      0,
      index === 0 ? 0 : 0.18
    ]);
    const declarations = cards.map(([x, y, angle], index) => `
      vec2 deckCenter${index} = mix(vec2(${x.toFixed(2)}, ${y.toFixed(2)}), vec2(0.0), pMerge);
      vec2 deckPoint${index} = rotate2d(${angle.toFixed(2)} * (1.0 - pMerge)) * (st - deckCenter${index});
      vec2 deckSize${index} = mix(vec2(${deckHalfWidth.toFixed(4)}, 0.245), vec2(0.58, 0.42), pMerge);
      float dShape${index} = sdRoundedBox(deckPoint${index}, deckSize${index}, mix(0.035, 0.045, pMerge));
    `).join('');
    const union = cards.slice(1).reduce(
      (current, _, index) => combineCall(current, `dShape${index + 1}`),
      'dShape0'
    );
    return `${declarations}\nfloat dShapes = ${union};`;
  }

  if (config.layout === 'petals') {
    const petals = Array.from({ length: 5 }, (_, index) => {
      const angle = index * Math.PI * 2 / 5;
      const x = Math.cos(angle) * 0.20;
      const y = Math.sin(angle) * 0.20;
      return [x, y, angle - Math.PI / 2];
    });
    const declarations = petals.map(([x, y, angle], index) => `
      vec2 petalCenter${index} = mix(vec2(${x.toFixed(4)}, ${y.toFixed(4)}), vec2(0.0), pMerge);
      vec2 petalPoint${index} = rotate2d(${angle.toFixed(4)}) * (st - petalCenter${index});
      float dShape${index} = sdEllipseApprox(petalPoint${index}, mix(vec2(0.115, 0.23), vec2(0.58, 0.44), pMerge));
    `).join('');
    const union = petals.slice(1).reduce((current, _, index) => combineCall(current, `dShape${index + 1}`), 'dShape0');
    return `${declarations}\nfloat dShapes = ${union};`;
  }

  if (config.layout === 'filmStrip') {
    const frames = [[-0.68, 0.02, -0.12], [-0.34, 0.10, -0.06], [0, 0.0, 0], [0.34, -0.10, 0.06], [0.68, -0.02, 0.12]];
    const declarations = frames.map(([x, y, angle], index) => `
      vec2 frameCenter${index} = mix(vec2(${x}, ${y}), vec2(0.0), pMerge);
      vec2 framePoint${index} = rotate2d(${Number(angle).toFixed(4)}) * (st - frameCenter${index});
      vec2 frameSize${index} = mix(vec2(0.15, 0.28), vec2(0.58, 0.42), pMerge);
      float dShape${index} = sdRoundedBox(framePoint${index}, frameSize${index}, 0.035);
    `).join('');
    const union = frames.slice(1).reduce((current, _, index) => combineCall(current, `dShape${index + 1}`), 'dShape0');
    return `${declarations}\nfloat dShapes = ${union};`;
  }

  if (config.layout === 'audioSpectrum') {
    const bars = [0.14, 0.23, 0.34, 0.46, 0.30, 0.43, 0.32, 0.22, 0.14];
    const barHalfWidth = 0.055;
    const barPitch = barHalfWidth * 2 + GAP_PX / 688;
    const declarations = bars.map((height, index) => {
      const x = (index - (bars.length - 1) / 2) * barPitch;
      return `
        vec2 spectrumCenter${index} = mix(vec2(${x.toFixed(2)}, 0.0), vec2(0.0), pMerge);
        vec2 spectrumSize${index} = mix(vec2(${barHalfWidth.toFixed(3)}, ${height.toFixed(2)}), vec2(0.58, 0.42), pMerge);
        float dShape${index} = sdRoundedBox(
          st - spectrumCenter${index},
          spectrumSize${index},
          mix(0.045, 0.045, pMerge)
        );
      `;
    }).join('');
    const union = bars.slice(1).reduce(
      (current, _, index) => combineCall(current, `dShape${index + 1}`),
      'dShape0'
    );
    return `${declarations}\nfloat dShapes = ${union};`;
  }

  if (config.layout === 'waveTiles') {
    const cards = [[-0.68, -0.10, -0.14], [-0.34, 0.08, -0.07], [0, 0.16, 0], [0.34, 0.08, 0.07], [0.68, -0.10, 0.14]];
    const declarations = cards.map(([x, y, angle], index) => `
      vec2 waveCenter${index} = mix(vec2(${x}, ${y}), vec2(0.0), pMerge);
      vec2 wavePoint${index} = rotate2d(${Number(angle).toFixed(4)}) * (st - waveCenter${index});
      vec2 waveSize${index} = mix(vec2(0.16, 0.30), vec2(0.58, 0.42), pMerge);
      float dShape${index} = sdRoundedBox(wavePoint${index}, waveSize${index}, 0.05);
    `).join('');
    const union = cards.slice(1).reduce((current, _, index) => combineCall(current, `dShape${index + 1}`), 'dShape0');
    return `${declarations}\nfloat dShapes = ${union};`;
  }

  const count = Math.max(2, Math.min(7, config.cardCount || 3));
  const totalWidth = 1224 / 688;
  const startGap = 16 / 688;
  const startWidth = (totalWidth - startGap * (count - 1)) / count;
  const declarations = Array.from({ length: count }, (_, index) => {
    const offset = index - (count - 1) / 2;
    return `
      float cardCenter${index} = ${offset.toFixed(1)} * (cardWidth + cardGap);
      float dShape${index} = sdRoundedBox(
        st - vec2(cardCenter${index}, 0.0),
        vec2(cardWidth * 0.5, 0.5),
        cardRadius
      );
    `;
  }).join('');
  const union = Array.from({ length: count - 1 }, (_, index) => index + 1).reduce(
    (current, index) => combineCall(current, `dShape${index}`),
    'dShape0'
  );

  return `
    float cardGap = mix(${startGap.toFixed(6)}, 0.0, pMerge);
    float cardWidth = mix(${startWidth.toFixed(6)}, ${(totalWidth / count).toFixed(6)}, pMerge);
    float cardRadius = mix(0.045, 0.045, pMerge);
    ${declarations}
    float dShapes = ${union};
  `;
}

