`
      uniform vec2 u_resolution;
      uniform float u_progress;
      uniform vec2 u_mouse;
      uniform float u_velocity;
      uniform float u_mediaAspect;
      uniform sampler2D u_media;
      uniform sampler2D u_wordmark;

      varying vec2 vUv;

      float smin(float a, float b, float k) {
        float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
        return mix(b, a, h) - k * h * (1.0 - h);
      }

      float sdRoundedBox(vec2 p, vec2 b, float r) {
        vec2 q = abs(p) - b + vec2(r);
        return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - r;
      }

      mat2 rotate2d(float angle) {
        float c = cos(angle);
        float s = sin(angle);
        return mat2(c, -s, s, c);
      }

      float sdEllipseApprox(vec2 p, vec2 radius) {
        return (length(p / radius) - 1.0) * min(radius.x, radius.y);
      }

      float sdArch(vec2 p, vec2 size) {
        float body = sdRoundedBox(p - vec2(0.0, -size.y * 0.22), vec2(size.x, size.y * 0.72), 0.025);
        float dome = length(p - vec2(0.0, size.y * 0.48)) - size.x;
        return min(body, dome);
      }


      void main() {
        float aspect = u_resolution.x / u_resolution.y;
        vec2 st = (vUv - 0.5) * vec2(aspect, 1.0);

        float arch = sin(vUv.x * 3.14159265);
        st.y += arch * u_velocity * 0.04;

        float pinch = cos(st.y * 3.14159265 * 2.0);
        st.x += pinch * u_velocity * 0.02;

        float p = clamp(u_progress, 0.0, 1.0);

        float pMerge  = smoothstep(0.10, 0.90, p);
        float pFinal  = smoothstep(
          ${Number(config.finalBlendStart ?? 0.85).toFixed(2)},
          ${Number(config.finalBlendEnd ?? 1.0).toFixed(2)},
          p
        );
        float totalW      = 1224.0 / 688.0;
        float blendK = ${config.enableLiquid ? 'sin(pMerge * 3.14159265) * 0.16 + 0.002' : '0.001'};

        ${shapeShader}

        ${config.finalShape === 'wordmark' ? `
          float wordmarkSdf = texture2D(u_wordmark, vUv).r;
          float dWordmark = (wordmarkSdf - 0.5) * 0.34;
        ` : ''}
        float dFinalShape = ${config.finalShape === 'wordmark'
          ? 'dWordmark'
          : config.finalShape === 'circle'
          ? 'length(st) - 0.50'
          : config.finalShape === 'square'
            ? 'sdRoundedBox(st, vec2(0.50), 0.035)'
            : 'sdRoundedBox(st, vec2(totalW * 0.5, 0.5), 32.0 / 688.0)'};
        float dResult = mix(dShapes, dFinalShape, pFinal);
        float morphEnergy = sin(p * 3.14159265);
        float surfaceTension = (
          sin(st.x * 18.0 + p * 8.0)
          + sin((st.x + st.y) * 27.0 - p * 6.0) * 0.52
          + cos(st.y * 22.0 + p * 7.0) * 0.34
        ) * (0.0028 + abs(u_velocity) * 0.0022) * morphEnergy;
        dResult += surfaceTension;

        float edgeAA = max(fwidth(dResult), 1.15 / min(u_resolution.x, u_resolution.y));
        vec2 fieldGradient = vec2(dFdx(dResult), dFdy(dResult));
        vec2 fieldNormal = fieldGradient / max(length(fieldGradient), 0.00001);
        float edgeDepth = clamp(-dResult / 0.035, 0.0, 1.0);
        float glassLip = (1.0 - smoothstep(0.05, 1.0, edgeDepth)) * morphEnergy;
        float liquidSheen = ${config.enableLiquid
          ? `glassLip * ${Number(config.liquidSheen ?? 0.16).toFixed(2)}`
          : '0.0'};

        float shapeAlpha = 1.0 - smoothstep(-edgeAA, edgeAA, dResult);
        float alpha = shapeAlpha;

        vec2 coverScale = vec2(1.0);
        if (u_mediaAspect > aspect) {
          coverScale.x = aspect / u_mediaAspect;
        } else {
          coverScale.y = u_mediaAspect / aspect;
        }

        ${config.enableCursorFollow ? `
          vec2 mediaOffset = u_mouse * 0.035;
          vec2 centeredUv = (vUv - 0.5) * coverScale * 0.95 + 0.5;
          vec2 parallaxUV = centeredUv - mediaOffset;
        ` : `
          vec2 parallaxUV = (vUv - 0.5) * coverScale + 0.5;
        `}

        vec2 refractedUv = parallaxUV + fieldNormal * glassLip * (0.010 + abs(u_velocity) * 0.006);
        vec2 fringe = fieldNormal * glassLip * 0.0022;
        vec2 safeUv = clamp(refractedUv, 0.0, 1.0);
        vec4 mediaColor = texture2D(u_media, safeUv);
        vec3 refractedColor = vec3(
          texture2D(u_media, clamp(safeUv + fringe, 0.0, 1.0)).r,
          mediaColor.g,
          texture2D(u_media, clamp(safeUv - fringe, 0.0, 1.0)).b
        );
        vec3 finalColor = refractedColor + vec3(0.92, 1.0, 0.96) * liquidSheen;

        gl_FragColor = vec4(finalColor, mediaColor.a * alpha);
      }
      `

maskTemplate:
`
      uniform vec2 uResolution;
      uniform float uProgress;
      uniform float uVelocity;
      uniform vec2 uPointer;
      uniform float uVideoAspect;
      uniform sampler2D uVideo;
      uniform sampler2D uMask;
      varying vec2 vUv;

      float roundedBox(vec2 point, vec2 size, float radius) {
        vec2 q = abs(point) - size + radius;
        return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - radius;
      }

      void main() {
        float p = smoothstep(.04, .96, uProgress);
        vec2 point = vUv - .5;
        point.y += sin(vUv.x * 3.14159265) * uVelocity * .028;
        point.x += cos(vUv.y * 6.2831853) * uVelocity * .014;

        float liquidPhase = sin(p * 3.14159265);
        vec2 maskUv = vUv;
        maskUv.x += (
          sin(vUv.y * 18.0 + p * 8.0) +
          sin((vUv.x + vUv.y) * 29.0 - p * 5.0) * .45
        ) * .013 * liquidPhase;
        maskUv.y += (
          sin(vUv.x * 15.0 - p * 7.0) +
          cos((vUv.x - vUv.y) * 24.0 + p * 6.0) * .40
        ) * .012 * liquidPhase;

        float squareDistance = roundedBox(point, vec2(.46), .035);
        float maskBounds = step(0.0, maskUv.x) * step(maskUv.x, 1.0) * step(0.0, maskUv.y) * step(maskUv.y, 1.0);
        float maskDistance = (texture2D(uMask, clamp(maskUv, 0.0, 1.0)).r - .5) * .44;
        maskDistance = mix(.22, maskDistance, maskBounds);
        maskDistance += (
          sin((maskUv.x + maskUv.y) * 31.0 + p * 10.0) +
          sin(maskUv.y * 43.0 - p * 8.0)
        ) * .0065 * liquidPhase;

        float distance = mix(squareDistance, maskDistance, p) - liquidPhase * .010;
        float edgeSoftness = max(fwidth(distance), 1.15 / min(uResolution.x, uResolution.y));
        float alpha = 1.0 - smoothstep(-edgeSoftness, edgeSoftness, distance);
        vec2 distanceGradient = vec2(dFdx(distance), dFdy(distance));
        vec2 surfaceNormal = distanceGradient / max(length(distanceGradient), .00001);
        float edgeDepth = clamp(-distance / .035, 0.0, 1.0);
        float glassLip = (1.0 - smoothstep(.05, 1.0, edgeDepth)) * liquidPhase;

        vec2 videoUv = vUv;
        if (uVideoAspect > 1.0) {
          videoUv.x = (videoUv.x - .5) / uVideoAspect + .5;
        } else {
          videoUv.y = (videoUv.y - .5) * uVideoAspect + .5;
        }
        videoUv = videoUv - uPointer * .018;
        vec2 refractedUv = videoUv + surfaceNormal * glassLip * (.011 + abs(uVelocity) * .006);
        vec2 fringe = surfaceNormal * glassLip * .0022;
        vec2 safeUv = clamp(refractedUv, 0.0, 1.0);
        vec3 centerColor = texture2D(uVideo, safeUv).rgb;
        vec3 color = vec3(
          texture2D(uVideo, clamp(safeUv + fringe, 0.0, 1.0)).r,
          centerColor.g,
          texture2D(uVideo, clamp(safeUv - fringe, 0.0, 1.0)).b
        );
        color += vec3(.92, 1.0, .96) * glassLip * .16;
        gl_FragColor = vec4(color, alpha);
      }
    `

