function createWordmarkTexture(text) {
  if (!text) return emptyMaskTexture;

  const width = 1024;
  const height = 576;
  const maxDistance = 96;
  const pixels = new Uint8Array(width * height * 4);
  pixels.fill(255);
  const wordmarkTexture = new THREE.DataTexture(pixels, width, height, THREE.RGBAFormat);
  wordmarkTexture.minFilter = THREE.LinearFilter;
  wordmarkTexture.magFilter = THREE.LinearFilter;
  wordmarkTexture.generateMipmaps = false;
  wordmarkTexture.flipY = true;
  wordmarkTexture.needsUpdate = true;

  const wordmarkCanvas = document.createElement('canvas');
  wordmarkCanvas.width = width;
  wordmarkCanvas.height = height;
  const context = wordmarkCanvas.getContext('2d', { willReadFrequently: true });

  const distanceTransform = (inside, targetValue) => {
    const distances = new Float32Array(width * height);
    const infinity = 1e6;
    const diagonal = Math.SQRT2;
    for (let index = 0; index < distances.length; index += 1) {
      distances[index] = inside[index] === targetValue ? 0 : infinity;
    }
    for (let y = 0; y < height; y += 1) {
      for (let x = 0; x < width; x += 1) {
        const index = y * width + x;
        let value = distances[index];
        if (x) value = Math.min(value, distances[index - 1] + 1);
        if (y) value = Math.min(value, distances[index - width] + 1);
        if (x && y) value = Math.min(value, distances[index - width - 1] + diagonal);
        if (x + 1 < width && y) value = Math.min(value, distances[index - width + 1] + diagonal);
        distances[index] = value;
      }
    }
    for (let y = height - 1; y >= 0; y -= 1) {
      for (let x = width - 1; x >= 0; x -= 1) {
        const index = y * width + x;
        let value = distances[index];
        if (x + 1 < width) value = Math.min(value, distances[index + 1] + 1);
        if (y + 1 < height) value = Math.min(value, distances[index + width] + 1);
        if (x + 1 < width && y + 1 < height) value = Math.min(value, distances[index + width + 1] + diagonal);
        if (x && y + 1 < height) value = Math.min(value, distances[index + width - 1] + diagonal);
        distances[index] = value;
      }
    }
    return distances;
  };

  const buildWordmarkSdf = () => {
    context.clearRect(0, 0, width, height);
    context.fillStyle = '#ffffff';
    context.textAlign = 'center';
    context.textBaseline = 'middle';
    context.font = '600 152px "Familjen Grotesk", "DM Sans", sans-serif';

    const safeWidth = width * 0.78;
    const measuredWidth = context.measureText(text).width;
    if (measuredWidth > safeWidth) {
      const fittedSize = Math.floor(152 * safeWidth / measuredWidth);
      context.font = `600 ${fittedSize}px "Familjen Grotesk", "DM Sans", sans-serif`;
    }

    context.fillText(text, width / 2, height / 2);
    const rgba = context.getImageData(0, 0, width, height).data;
    const inside = new Uint8Array(width * height);
    for (let index = 0; index < inside.length; index += 1) {
      inside[index] = rgba[index * 4 + 3] > 96 ? 1 : 0;
    }
    const toInside = distanceTransform(inside, 1);
    const toOutside = distanceTransform(inside, 0);
    for (let index = 0; index < inside.length; index += 1) {
      const signed = inside[index] ? -toOutside[index] : toInside[index];
      const encoded = Math.round((Math.max(-maxDistance, Math.min(maxDistance, signed)) / maxDistance * .5 + .5) * 255);
      const pixel = index * 4;
      pixels[pixel] = encoded;
      pixels[pixel + 1] = encoded;
      pixels[pixel + 2] = encoded;
      pixels[pixel + 3] = 255;
    }
    wordmarkTexture.needsUpdate = true;
  };

  document.fonts.ready.then(() => {
    requestAnimationFrame(buildWordmarkSdf);
  });

  return wordmarkTexture;
}

