    const distances = new Float32Array(size * size);
    const infinity = 1e6;
    const diagonal = Math.SQRT2;

    for (let index = 0; index < distances.length; index += 1) {
      distances[index] = inside[index] === targetValue ? 0 : infinity;
    }

    for (let y = 0; y < size; y += 1) {
      for (let x = 0; x < size; x += 1) {
        const index = y * size + x;
        let distance = distances[index];
        if (x > 0) distance = Math.min(distance, distances[index - 1] + 1);
        if (y > 0) distance = Math.min(distance, distances[index - size] + 1);
        if (x > 0 && y > 0) distance = Math.min(distance, distances[index - size - 1] + diagonal);
        if (x + 1 < size && y > 0) distance = Math.min(distance, distances[index - size + 1] + diagonal);
        distances[index] = distance;
      }
    }

    for (let y = size - 1; y >= 0; y -= 1) {
      for (let x = size - 1; x >= 0; x -= 1) {
        const index = y * size + x;
        let distance = distances[index];
        if (x + 1 < size) distance = Math.min(distance, distances[index + 1] + 1);
