  };

  const distanceToInside = distanceTransform(1);
  const distanceToOutside = distanceTransform(0);
  const sdfPixels = new Uint8Array(size * size * 4);

  for (let index = 0; index < inside.length; index += 1) {
    const signedDistance = inside[index]
      ? -distanceToOutside[index]
