function distanceTransform(inside, size, target) {
  const distances = new Float32Array(size * size);
  const infinity = 1e6;
  const diagonal = Math.SQRT2;
  for (let index = 0; index < distances.length; index += 1) {
    distances[index] = inside[index] === target ? 0 : infinity;
  }
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const index = y * size + x;
      let value = distances[index];
      if (x) value = Math.min(value, distances[index - 1] + 1);
      if (y) value = Math.min(value, distances[index - size] + 1);
      if (x && y) value = Math.min(value, distances[index - size - 1] + diagonal);
      if (x + 1 < size && y) value = Math.min(value, distances[index - size + 1] + diagonal);
      distances[index] = value;
    }
  }
  for (let y = size - 1; y >= 0; y -= 1) {
    for (let x = size - 1; x >= 0; x -= 1) {
      const index = y * size + x;
      let value = distances[index];
      if (x + 1 < size) value = Math.min(value, distances[index + 1] + 1);
      if (y + 1 < size) value = Math.min(value, distances[index + size] + 1);
      if (x + 1 < size && y + 1 < size) value = Math.min(value, distances[index + size + 1] + diagonal);
      if (x && y + 1 < size) value = Math.min(value, distances[index + size - 1] + diagonal);
      distances[index] = value;
    }
  }
  return distances;
}

