function createSdfTexture(url) {
  const size = 1024;
  const maxDistance = 192;
  const pixels = new Uint8Array(size * size * 4);
  pixels.fill(255);
  const texture = new THREE.DataTexture(pixels, size, size, THREE.RGBAFormat);
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.generateMipmaps = false;
  texture.flipY = true;
  texture.needsUpdate = true;

  const image = new Image();
  image.onload = () => {
    enqueueSdfJob(() => {
      const canvas = document.createElement('canvas');
      canvas.width = size;
      canvas.height = size;
      const context = canvas.getContext('2d', { willReadFrequently: true });
      const aspect = image.naturalWidth / image.naturalHeight;
      const maxSize = size * .82;
      const width = aspect >= 1 ? maxSize : maxSize * aspect;
      const height = aspect >= 1 ? maxSize / aspect : maxSize;
      context.drawImage(image, (size - width) / 2, (size - height) / 2, width, height);
      const rgba = context.getImageData(0, 0, size, size).data;
      const inside = new Uint8Array(size * size);
      for (let index = 0; index < inside.length; index += 1) {
        inside[index] = rgba[index * 4 + 3] > 96 ? 1 : 0;
      }
      const toInside = distanceTransform(inside, size, 1);
      const toOutside = distanceTransform(inside, size, 0);
      for (let index = 0; index < inside.length; index += 1) {
        const signed = inside[index] ? -toOutside[index] : toInside[index];
        const encoded = Math.round((Math.max(-maxDistance, Math.min(maxDistance, signed)) / maxDistance * .5 + .5) * 255);
        const pixel = index * 4;
        pixels[pixel] = encoded;
        pixels[pixel + 1] = encoded;
        pixels[pixel + 2] = encoded;
        pixels[pixel + 3] = 255;
      }
      texture.needsUpdate = true;
    });
  };
  const shapeKey = url.split('/').pop().replace('.svg', '');
  image.src = window.AFRICAN_SHAPE_URLS?.[shapeKey] || url;
  return texture;
}

